<script setup>
import { onMounted, ref, computed, watch } from 'vue';
import { ElMessage } from 'element-plus';
import { apiClient } from '../../utils/api.js';
import { materialMatches, materialBindings, materialCoversFitments } from '../../../../src/shared/workflow-materials.js';
import WorkflowMaterialLibrary from './WorkflowMaterialLibrary.vue';
import WorkflowValuePreview from './WorkflowValuePreview.vue';
const props=defineProps({modelValue:{type:Array,default:()=>[]},label:{type:String,default:'引用生产资料'},imageReferences:{type:Boolean,default:true},direct:Boolean,category:{type:Object,default:()=>({})},fitments:{type:Array,default:()=>[]},autoSelect:Boolean,disabled:Boolean}),emit=defineEmits(['update:modelValue']);
const records=ref([]),open=ref(false),loading=ref(false),keyword=ref(''),error=ref('');
const selected=computed(()=>props.modelValue.map(ref=>ref.id));
const selectedRecords=computed(()=>props.modelValue.map(ref=>({ref,record:records.value.find(r=>r.id===ref.id)})).filter(x=>x.record));
const candidates=computed(()=>records.value.filter(r=>(!props.direct||r.payload.images.length)&&materialMatches(r,{category:props.category,fitments:props.fitments,keyword:keyword.value})));
const stale=computed(()=>!loading.value&&props.modelValue.filter(ref=>!records.value.some(r=>r.id===ref.id&&r.revision===ref.revision)));
const optionLabel=r=>[r.name,...materialBindings(r.payload).flatMap(b=>[b.brand,...b.models]),r.payload.category].filter(Boolean).join(' · ');
async function load(){loading.value=true;error.value='';try{const [materials,keys]=await Promise.all([apiClient.get('/api/product-workflows/materials',{noCache:true}),apiClient.get('/api/product-workflows/key-models',{noCache:true})]);records.value=[...materials,...keys];}catch(e){error.value=e.message;ElMessage.error(e.message);}finally{loading.value=false;}}
function change(ids){const list=props.direct?(ids?[ids]:[]):ids;emit('update:modelValue',list.map(id=>{const r=records.value.find(r=>r.id===id);return {id,kind:r?.kind||props.modelValue.find(ref=>ref.id===id)?.kind||'material',revision:r?.revision||1,...(props.direct?{imageIndex:props.modelValue.find(ref=>ref.id===id)?.imageIndex||0}:{})};}));}
function chooseIndex(id,index){emit('update:modelValue',props.modelValue.map(ref=>ref.id===id?{...ref,imageIndex:index}:ref));}
watch([candidates,()=>props.modelValue,()=>props.fitments],()=>{if(!props.autoSelect||props.disabled||loading.value||props.modelValue.length||!props.fitments.length)return;const exact=candidates.value.filter(r=>materialBindings(r.payload).length&&materialCoversFitments(r,props.fitments));if(exact.length===1)change(props.direct?exact[0].id:[exact[0].id]);});
onMounted(load);
</script>
<template><div class="material-references" :class="{'direct-mode':direct}"><div class="references-head"><strong>{{ label }}</strong><el-button link type="primary" :disabled="disabled" @click="open=true">新增 / 管理资料</el-button></div><el-input v-model="keyword" clearable placeholder="按名称、品牌或型号筛选资料" :disabled="disabled"/><el-select :model-value="direct?(selected[0]||''):selected" :multiple="!direct" filterable clearable :disabled="disabled" :loading="loading" placeholder="选择资料，选中后可预览确认" @visible-change="$event&&load()" @change="change"><el-option v-for="record in candidates" :key="record.id" :value="record.id" :label="optionLabel(record)"/><el-option v-for="ref in modelValue.filter(ref=>!candidates.some(r=>r.id===ref.id))" :key="ref.id" :value="ref.id" :label="records.find(r=>r.id===ref.id)?.name||'资料已停用或不可用，请移除'"/></el-select><small v-if="fitments.length">已按当前类目及所选品牌、型号筛选，同时保留通用资料；多份资料由你选择。</small><small v-else>{{ direct?'直接使用所选原图，不调用 AI。可选择这份资料中的具体图片。':imageReferences?'图片与文字说明一起提供给当前节点。':'文本节点只引用资料说明。' }}</small><div v-for="{ref,record} in selectedRecords" :key="ref.id" class="selected-material"><strong>{{ record.name }}</strong><small>{{ record.payload.listingCategory?.name||'通用 / 尚未分类' }} · {{ materialBindings(record.payload).map(b=>`${b.brand} ${b.models.join('、')}`).join('；')||'未限制品牌型号' }}</small><WorkflowValuePreview :value="direct?[record.payload.images[ref.imageIndex||0]]:record.payload.images" format="images"/><el-radio-group v-if="direct&&record.payload.images.length>1" :model-value="ref.imageIndex||0" :disabled="disabled" @change="chooseIndex(ref.id,$event)"><el-radio-button v-for="(_,i) in record.payload.images" :key="i" :value="i">图 {{ i+1 }}</el-radio-button></el-radio-group><WorkflowValuePreview v-if="record.payload.notes" :value="record.payload.notes" label="资料文字预览"/></div><el-alert v-if="stale.length&&!error" type="warning" :closable="false" title="引用资料已更新或停用，请更新引用或移除后重新选择。"><el-button link :disabled="disabled" @click="change(direct?(selected.find(id=>records.some(r=>r.id===id))||''):selected.filter(id=>records.some(r=>r.id===id)))">更新引用</el-button></el-alert><el-dialog v-model="open" title="企业生产资料库" width="1100px" top="4vh" append-to-body><WorkflowMaterialLibrary v-if="open" :category="category" :seed="{bindings:fitments.reduce((rows,f)=>{let b=rows.find(b=>b.brand===f.brand);if(!b){b={brand:f.brand,models:[]};rows.push(b);}b.models.push(f.model);return rows;},[])}" @saved="load"/></el-dialog></div></template>
<style scoped>.references-head{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px}.references-head strong{font-size:13px}.el-select{width:100%;margin-top:8px}small{display:block;margin-top:8px;font-size:12px;line-height:1.6;color:var(--el-text-color-secondary)}.material-references{margin:12px 0}.selected-material{margin-top:10px;padding:10px;border:1px solid var(--el-border-color-lighter);border-radius:6px}.selected-material>strong{font-size:13px}.selected-material .value-preview{margin-top:8px}.direct-mode{display:grid;grid-template-columns:minmax(220px,1fr) minmax(180px,280px);gap:10px;align-items:start}.direct-mode>.references-head{grid-column:1/-1;margin:0}.direct-mode>.el-input{grid-column:1}.direct-mode>.el-select{grid-column:1;margin:0}.direct-mode>small{grid-column:1;margin:0}.direct-mode>.selected-material{grid-column:2;grid-row:2/span 4;margin:0}.direct-mode :deep(.preview-images .el-image){width:100px;height:134px}.direct-mode :deep(.value-preview p){max-height:68px}@media(max-width:650px){.direct-mode{display:block}.direct-mode>.selected-material{margin-top:10px}}
</style>
